// Data-driven tests for batch88:
//   platform/policy/common/policy.ts (runtime logic)
//   base/common/product.ts (type-only -> zero exports)
// Truth generated by tool/ts2dart/_batch88_truth.cjs from real TS sources.
import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/product.dart' as prod;
import 'package:semi_design_flutter/src/monaco/platform/policy/common/policy.dart'
    as pol;

Map<String, dynamic> _truth() =>
    (jsonDecode(_truthJson) as Map).cast<String, dynamic>();

void main() {
  final t = _truth();

  group('batch88 product.ts (type-only)', () {
    test('TS exports nothing at runtime; Dart carriers are constructible', () {
      expect(t['productExports'], isEmpty);
      final agent = prod.IAgentSdkProductConfig(
          version: '0.3.168', urlTemplate: 'https://x/{sdkTarget}.tgz');
      expect(agent.version, '0.3.168');
      final chat = prod.IDefaultChatAgent(
        extensionId: 'e', chatExtensionId: 'c', chatExtensionOutputId: 'co',
        chatExtensionOutputExtensionStateCommand: 'cs',
        documentationUrl: 'd', skusDocumentationUrl: 's',
        optimizeUsageDocumentationUrl: 'o', publicCodeMatchesUrl: 'p',
        managePlanUrl: 'm', upgradePlanUrl: 'u', signUpUrl: 'su',
        termsStatementUrl: 't', privacyStatementUrl: 'pr',
        provider: const <String, Map<String, String>>{
          'default': <String, String>{'id': 'd', 'name': 'D'}
        },
        providerExtensionId: 'pe', providerUriSetting: 'ps',
        providerScopes: const <List<String>>[],
        entitlementUrl: 'eu', entitlementSignupLimitedUrl: 'es',
        tokenEntitlementUrl: 'te', mcpRegistryDataUrl: 'mr',
        managedSettingsUrl: 'ms', chatQuotaExceededContext: 'cq',
        completionsQuotaExceededContext: 'cq2', walkthroughCommand: 'w',
        completionsMenuCommand: 'cm', chatRefreshTokenCommand: 'cr',
        generateCommitMessageCommand: 'gc', resolveMergeConflictsCommand: 'rm',
        completionsAdvancedSetting: 'ca', completionsEnablementSetting: 'ce',
        nextEditSuggestionsSetting: 'ne',
      );
      expect(chat.extensionId, 'e');
      final cfg = prod.IProductConfiguration(
        version: '1', nameShort: 'VS', nameLong: 'Visual Studio Code',
        applicationName: 'code', urlProtocol: 'vscode', dataFolderName: '.vscode',
        sharedDataFolderName: '.vscode-shared',
        extensionProperties: const <String, Map<String, Object?>>{},
        builtInExtensionsEnabledWithAutoUpdates: const <String>[],
        serverApplicationName: 'server', defaultChatAgent: chat,
      );
      expect(cfg.version, '1');
      expect(cfg.defaultChatAgent, same(chat));
    });
  });

  group('batch88 policy.ts', () {
    test('policyExports match TS runtime surface', () {
      final expected = List<String>.from(t['policyExports'] as List)..sort();
      expect(['AbstractPolicyService', 'IPolicyService', 'NullPolicyService',
        'PolicyValueSource', 'getRestrictedPolicyValue',
        'toSerializablePolicyDefinition'], expected);
    });

    test('IPolicyService decorator id matches', () {
      expect(pol.IPolicyService.serviceId, t['decoratorId']);
    });

    test('PolicyValueSource enum values match', () {
      final expected = Map<String, String>.from(
          (t['policyValueSource'] as Map).cast<String, String>());
      final actual = <String, String>{
        'Device': pol.PolicyValueSource.Device,
        'NativeMdm': pol.PolicyValueSource.NativeMdm,
        'ServerManagedSettings': pol.PolicyValueSource.ServerManagedSettings,
        'FileManagedSettings': pol.PolicyValueSource.FileManagedSettings,
        'MixedManagedSettings': pol.PolicyValueSource.MixedManagedSettings,
        'Account': pol.PolicyValueSource.Account,
        'AccountGate': pol.PolicyValueSource.AccountGate,
      };
      expect(actual, expected);
    });

    test('toSerializablePolicyDefinition drops value callback', () {
      final e = (t['toSerializable'] as Map).cast<String, dynamic>();
      final d = pol.PolicyDefinition(
        type: 'string',
        value: (_) => 'computed',
        restrictedValue: 'rv',
        managedSettings: const <String, Object?>{'ms': 1},
      );
      final s = pol.toSerializablePolicyDefinition(d);
      expect(s.value, isNull); // hasValueKey:false in TS
      expect(s.type, e['type']);
      expect(s.restrictedValue, e['restrictedValue']);
      expect(s.managedSettings, e['managedSettings']);
    });

    test('getRestrictedPolicyValue matches (incl falsy restricted)', () {
      final e = (t['restricted'] as Map).cast<String, dynamic>();
      expect(pol.getRestrictedPolicyValue(
          pol.PolicyDefinition(type: 'boolean', restrictedValue: true)),
          e['withRestricted']);
      expect(pol.getRestrictedPolicyValue(pol.PolicyDefinition(type: 'boolean')),
          e['boolDefault']);
      expect(pol.getRestrictedPolicyValue(pol.PolicyDefinition(type: 'number')),
          e['numberDefault']);
      expect(pol.getRestrictedPolicyValue(pol.PolicyDefinition(type: 'string')),
          e['stringDefault']);
      expect(pol.getRestrictedPolicyValue(
          pol.PolicyDefinition(type: 'number', restrictedValue: 0)),
          e['numberRestrictedZero']);
      expect(pol.getRestrictedPolicyValue(
          pol.PolicyDefinition(type: 'string', restrictedValue: '')),
          e['stringRestrictedEmpty']);
    });

    test('AbstractPolicyService state machine matches TS truth', () async {
      final s = (t['service'] as Map).cast<String, dynamic>();
      final svc = _TestService();
      final defA = pol.PolicyDefinition(type: 'string');
      final defB = pol.PolicyDefinition(type: 'number', restrictedValue: 7);

      // first update
      final first = (s['first'] as Map).cast<String, dynamic>();
      final r1 = await svc.updatePolicyDefinitions(<String, pol.PolicyDefinition>{
        'a': defA, 'b': defB
      });
      expect(r1, first['result']);
      expect(svc.updateCalls.length, first['updateCalls']);
      expect(svc.policyDefinitions.keys.toList()..sort(), first['defs']);

      // same definition objects -> identity unchanged -> no re-update
      final same = (s['sameAgain'] as Map).cast<String, dynamic>();
      final r2 = await svc.updatePolicyDefinitions(<String, pol.PolicyDefinition>{
        'a': defA, 'b': defB
      });
      expect(r2, same['result']);
      expect(svc.updateCalls.length, same['updateCalls']);

      // new object for existing key -> changed -> re-update
      final chg = (s['changed'] as Map).cast<String, dynamic>();
      final changedDef = pol.PolicyDefinition(type: 'string');
      final r3 = await svc.updatePolicyDefinitions(<String, pol.PolicyDefinition>{
        'a': changedDef
      });
      expect(r3, chg['result']);
      expect(svc.updateCalls.length, chg['updateCalls']);
      expect(identical(svc.policyDefinitions['a'], changedDef), chg['defAIsNew']);

      // transitions
      final tr = (s['transitions'] as Map).cast<String, dynamic>();
      expect(svc.updateValue('a', 'x'), tr['t1']);
      expect(svc.updateValue('a', 'x'), tr['t2']);
      expect(svc.updateValue('a', 'y', pol.PolicyValueSource.Account), tr['t3']);
      expect(svc.updateValue('b', 42, pol.PolicyValueSource.ServerManagedSettings), tr['t4']);
      expect(svc.updateValue('c', null, pol.PolicyValueSource.Device), tr['t5']);
      expect(svc.updateValue('b', null), tr['t6']);
      expect(svc.getPolicyValue('a'), tr['valueA']);
      expect(svc.getPolicyValueSource('a'), tr['sourceA']);
      expect(svc.getPolicyValue('b'), tr['valueB']); // undefined -> null in truth (absent key)
      expect(svc.getPolicyValueSource('b'), tr['sourceB']);
      expect(svc.getPolicyValue('c'), tr['valueC']);
      expect(svc.getPolicyValueSource('c'), tr['sourceC']);

      expect(svc.getValues(), s['values']);

      // onDidChange fire path
      List<dynamic>? fired;
      final d = svc.onDidChange((e) { fired = e as List<dynamic>; });
      svc.fireOnDidChange(<String>['a']);
      expect(fired, s['firedPayload']);
      d.dispose();

      // serialize: B has no value (deleted) -> TS JSON.stringify drops the key
      final ser = (s['serialized'] as Map).cast<String, dynamic>();
      final dartSer = svc.serialize();
      _expectSerialized(dartSer, ser);

      // clear
      svc.clearValues();
      final cleared = (s['cleared'] as Map).cast<String, dynamic>();
      expect(svc.getValues(), cleared['values']);
      expect(svc.getPolicyValue('a'), cleared['valueA']);
      expect(svc.getPolicyValueSource('a'), cleared['sourceA']);
    });

    test('NullPolicyService matches TS truth', () async {
      final e = (t['nullService'] as Map).cast<String, dynamic>();
      final svc = pol.NullPolicyService();
      expect(await svc.updatePolicyDefinitions(
          <String, pol.PolicyDefinition>{'a': pol.PolicyDefinition(type: 'string')}),
          e['updateResult']);
      expect(svc.getPolicyValue('a'), e['value']);
      expect(svc.getPolicyValueSource('a'), e['source']);
      expect(svc.serialize(), e['serialized']);
      expect(svc.policyDefinitions, e['policyDefinitions']);
      // onDidChangeIsNone: Event.None is a no-op returning a disposable
      final disp = svc.onDidChange((_) {});
      expect(disp, isNotNull);
      disp.dispose();
      expect(e['onDidChangeIsNone'], isTrue);
    });
  });
}

void _expectSerialized(
    Map<String, Map<String, Object?>> actual, Map<String, dynamic> expected) {
  expect(actual.keys.toList()..sort(), expected.keys.toList()..sort());
  for (final key in expected.keys) {
    final exp = (expected[key] as Map).cast<String, dynamic>();
    final act = actual[key]!;
    final expDef = (exp['definition'] as Map).cast<String, dynamic>();
    final actDef = act['definition'] as pol.PolicyDefinition;
    expect(actDef.type, expDef['type']);
    expect(actDef.restrictedValue, expDef['restrictedValue']);
    // TS dropped `value` when undefined (deleted policy B)
    if (exp.containsKey('value')) {
      expect(act['value'], exp['value']);
    } else {
      expect(act['value'], isNull);
    }
  }
}

class _TestService extends pol.AbstractPolicyService {
  final List<List<String>> updateCalls = <List<String>>[];

  @override
  Future<void> updatePolicyDefinitionsInternal(
      Map<String, pol.PolicyDefinition> defs) async {
    updateCalls.add(defs.keys.toList());
  }

  bool updateValue(String name, Object? value,
          [String source = pol.PolicyValueSource.Device]) =>
      updatePolicyValue(name, value, source);

  Map<String, Object?> getValues() => getPolicyValues();

  void clearValues() => clearPolicyValues();
}

